:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --success: #0f9b8e;
  --border: 3px solid var(--accent);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: var(--card-bg);
  border: var(--border);
  box-shadow: 6px 6px 0 #000;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.4rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.mode-indicator {
  font-size: 1.1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 3px;
}

.timer {
  font-size: clamp(3rem, 18vw, 5.5rem);
  font-weight: bold;
  letter-spacing: 4px;
  line-height: 1;
  color: var(--text);
  text-shadow: 3px 3px 0 #000;
  padding: 8px 0;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 24px;
  background: var(--accent);
  color: var(--text);
  border: 3px solid #000;
  box-shadow: 4px 4px 0 #000;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s, box-shadow 0.05s;
}

button:hover {
  background: #ff5c77;
}

button:focus-visible {
  outline: 3px solid var(--success);
  outline-offset: 3px;
}

button:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 #000;
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  background: var(--card-bg);
  border-color: var(--muted);
  box-shadow: 3px 3px 0 #000;
  color: var(--muted);
  padding: 8px 16px;
  font-size: 0.9rem;
}

.mode-btn.active {
  background: var(--accent);
  border-color: #000;
  color: var(--text);
}

.mode-btn:hover {
  background: #2a2a4a;
}

.mode-btn.active:hover {
  background: #ff5c77;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .timer {
    font-size: clamp(2.5rem, 16vw, 4rem);
  }
  button {
    padding: 10px 18px;
    font-size: 0.95rem;
  }
}

(function() {
  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const timerDisplay = document.getElementById('timerDisplay');
  const modeIndicator = document.getElementById('modeIndicator');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workModeBtn = document.getElementById('workModeBtn');
  const breakModeBtn = document.getElementById('breakModeBtn');

  let mode = 'work';
  let remaining = WORK_SECONDS;
  let running = false;
  let intervalId = null;
  let endTime = 0;

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return m + ':' + s;
  }

  function render() {
    timerDisplay.textContent = formatTime(remaining);
    modeIndicator.textContent = mode === 'work' ? 'Work' : 'Break';
    startPauseBtn.textContent = running ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
    workModeBtn.classList.toggle('active', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
  }

  function tick() {
    const now = Date.now();
    const diff = Math.max(0, Math.round((endTime - now) / 1000));
    if (diff !== remaining) {
      remaining = diff;
      render();
    }
    if (remaining <= 0) {
      stop();
      switchMode(mode === 'work' ? 'break' : 'work');
    }
  }

  function start() {
    if (running) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    intervalId = setInterval(tick, 200);
    render();
  }

  function stop() {
    running = false;
    if (intervalId) {
      clearInterval(intervalId);
      intervalId = null;
    }
    render();
  }

  function reset() {
    stop();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  function switchMode(newMode) {
    mode = newMode;
    stop();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  startPauseBtn.addEventListener('click', function() {
    if (running) {
      stop();
    } else {
      start();
    }
  });

  resetBtn.addEventListener('click', reset);

  workModeBtn.addEventListener('click', function() {
    if (mode !== 'work') switchMode('work');
  });

  breakModeBtn.addEventListener('click', function() {
    if (mode !== 'break') switchMode('break');
  });

  render();
})();
